  import math

  def safe_divide(a: float, b: float) -> float:
      if b == 0.0:
          if a > 0.0:
              return float('inf')
          elif a < 0.0:
              return float('-inf')
          else:
              return float('nan')
      else:
          result = a / b
          if math.isinf(result):
              return math.copysign(math.inf, a)
          return result
  ```

