**Example of Proper Dynamic SQL Construction**:
  ```python
  def build_select_query(table: str, filters: dict) -> tuple:
      allowed_tables = {"users", "orders"}
      if table not in allowed_tables:
          raise ValueError(f"Invalid table name: {table}. Allowed tables are: {allowed_tables}")
      columns = ["id", "name", "email"] if table == "users" else ["order_id", "customer_id", "total"]
      placeholders = ", ".join(["?"] * len(filters))
      conditions = [f"{key} = ?" for key in filters]
      query = f"SELECT {', '.join(columns)} FROM {table} WHERE {' AND '.join(conditions)}"
      params = list(filters.values())
      return (query, params)
  ```

