  ```python
  def parse_currency_to_cents(amount: str) -> int:
      if amount.startswith('-'):
          sign = -1
          amount = amount[1:]
      else:
          sign = 1
      parts = amount.split('.')
      dollars = int(parts[0])
      cents = int(parts[1]) * 10 if len(parts) > 1 and len(parts[1]) == 2 else int(parts[1]) * 100
      return sign * (dollars * 100 + cents)
